  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val PreferenceInterpreter_airCareSupervisionProcess_preferenceInterpreter_id = Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter.id
    val AirQualityAssessor_airCareSupervisionProcess_airQualityAssessor_id = Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_airQualityAssessor.id
    val HumidityAssessor_airCareSupervisionProcess_humidityAssessor_id = Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor.id
    val ObservationConfidenceGuardian_airCareSupervisionProcess_observationConfidenceGuardian_id = Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_observationConfidenceGuardian.id
    val AirCarePolicySupervisor_airCareSupervisionProcess_airCarePolicySupervisor_id = Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_airCarePolicySupervisor.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case PreferenceInterpreter_airCareSupervisionProcess_preferenceInterpreter_id =>
          val prefix = "PreferenceInterpreter_airCareSupervisionProcess_preferenceInterpreter_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Cabin_Air_Care_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Cabin_Air_Care_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Cabin_Air_Care_Supervisor._
                |
                |class ${suiteName} extends PreferenceInterpreter_airCareSupervisionProcess_preferenceInterpreter_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case AirQualityAssessor_airCareSupervisionProcess_airQualityAssessor_id =>
          val prefix = "AirQualityAssessor_airCareSupervisionProcess_airQualityAssessor_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Cabin_Air_Care_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Cabin_Air_Care_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Cabin_Air_Care_Supervisor._
                |
                |class ${suiteName} extends AirQualityAssessor_airCareSupervisionProcess_airQualityAssessor_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case HumidityAssessor_airCareSupervisionProcess_humidityAssessor_id =>
          val prefix = "HumidityAssessor_airCareSupervisionProcess_humidityAssessor_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Cabin_Air_Care_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Cabin_Air_Care_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Cabin_Air_Care_Supervisor._
                |
                |class ${suiteName} extends HumidityAssessor_airCareSupervisionProcess_humidityAssessor_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case ObservationConfidenceGuardian_airCareSupervisionProcess_observationConfidenceGuardian_id =>
          val prefix = "ObservationConfidenceGuardian_airCareSupervisionProcess_observationConfidenceGuardian_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Cabin_Air_Care_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Cabin_Air_Care_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Cabin_Air_Care_Supervisor._
                |
                |class ${suiteName} extends ObservationConfidenceGuardian_airCareSupervisionProcess_observationConfidenceGuardian_ScalaTest {
                |  val verbose: B = T
