                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case AirCarePolicySupervisor_airCareSupervisionProcess_airCarePolicySupervisor_id =>
          val prefix = "AirCarePolicySupervisor_airCareSupervisionProcess_airCarePolicySupervisor_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Cabin_Air_Care_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Cabin_Air_Care_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Cabin_Air_Care_Supervisor._
                |
                |class ${suiteName} extends AirCarePolicySupervisor_airCareSupervisionProcess_airCarePolicySupervisor_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case x => halt(s"Infeasible bridge id: $x")
