  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[scp_candidate.Cabin_Air_Care_Supervisor.PreferenceInterpreter_airCareSupervisionProcess_preferenceInterpreter_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_airCareIntent" ~> postContainer.api_airCareIntent.string
        return updates
      case scp_candidate.runtimemonitor.ObservationKind.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_airQualityAssessor_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[scp_candidate.Cabin_Air_Care_Supervisor.AirQualityAssessor_airCareSupervisionProcess_airQualityAssessor_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_airAssessment" ~> postContainer.api_airAssessment.string
